use rusqlite::Connection;

pub fn establish_connection() -> Result<Connection, String> {
    // Name of the secure computer file
    let db_path = "anyastro_sanchalan_secure.db";

    // Open or create the secure computer file
    let connection = Connection::open(db_path)
        .map_err(|e| format!("Failed to open the secure computer record file: {}", e))?;

    // Lock the computer file with the SQLCipher encryption key
    // Note: For the final Windows release, this password will be generated by the Windows security system (DPAPI)
    let company_security_key = "AnyAstro_Secure_Business_Key_2026";
    
    connection.execute(&format!("PRAGMA key = '{}';", company_security_key), [])
        .map_err(|e| format!("Failed to lock the computer records: {}", e))?;

    Ok(connection)
}